public class StylishIndentation {

    static final int MAX_LINES = 1005;
    static final int MAX_INDENT = 1005;

    // Counts of grouping symbols per line
    static int[] roundOpen = new int[MAX_LINES];
    static int[] roundClose = new int[MAX_LINES];
    static int[] curlyOpen = new int[MAX_LINES];
    static int[] curlyClose = new int[MAX_LINES];
    static int[] squareOpen = new int[MAX_LINES];
    static int[] squareClose = new int[MAX_LINES];

    // Cumulative counts
    static int[] cumRound = new int[MAX_LINES];
    static int[] cumCurly = new int[MAX_LINES];
    static int[] cumSquare = new int[MAX_LINES];

    static int[] indent = new int[MAX_LINES];

    static int n1, n2;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);

        while (true) {
            String line = br.readLine();
            if (line == null) break;
            String[] parts = line.split(" ");
            n1 = Integer.parseInt(parts[0]);
            n2 = Integer.parseInt(parts[1]);
            if (n1 == 0 && n2 == 0) break;

            // Reset arrays
            Arrays.fill(roundOpen, 0);
            Arrays.fill(roundClose, 0);
            Arrays.fill(curlyOpen, 0);
            Arrays.fill(curlyClose, 0);
            Arrays.fill(squareOpen, 0);
            Arrays.fill(squareClose, 0);
            Arrays.fill(cumRound, 0);
            Arrays.fill(cumCurly, 0);
            Arrays.fill(cumSquare, 0);
            Arrays.fill(indent, 0);

            // Read first program
            for (int i = 0; i < n1; i++) {
                String s = br.readLine();
                countSymbols(s, i);
            }

            // Compute cumulative counts for first program
            for (int i = 1; i < n1; i++) {
                cumRound[i] = cumRound[i-1] + roundOpen[i-1] - roundClose[i-1];
                cumCurly[i] = cumCurly[i-1] + curlyOpen[i-1] - curlyClose[i-1];
                cumSquare[i] = cumSquare[i-1] + squareOpen[i-1] - squareClose[i-1];
            }

            // Determine indentation for first program
            for (int i = 1; i < n1; i++) {
                indent[i] = indent[i-1];
                // Add indentation from previous line's opening symbols
                indent[i] += roundOpen[i-1] * 1; // R
                indent[i] += curlyOpen[i-1] * 2; // C
                indent[i] += squareOpen[i-1] * 3; // S
                // Subtract indentation from current line's closing symbols (they appear before the content)
                indent[i] -= roundClose[i] * 1;
                indent[i] -= curlyClose[i] * 2;
                indent[i] -= squareClose[i] * 3;
            }

            // Now find the mapping (R, C, S) that fits the first program
            // We'll store possible values
            boolean[][][] possible = new boolean[11][11][11];
            for (int r = 0; r <= 10; r++) {
                for (int c = 0; c <= 10; c++) {
                    for (int s = 0; s <= 10; s++) {
                        possible[r][c][s] = true;
                    }
                }
            }

            // For each line of first program, check constraints
            for (int i = 1; i < n1; i++) {
                int expectedIndent = indent[i];
                for (int r = 0; r <= 10; r++) {
                    for (int c = 0; c <= 10; c++) {
                        for (int s = 0; s <= 10; s++) {
                            if (!possible[r][c][s]) continue;
                            int calc = r * cumRound[i] + c * cumCurly[i] + s * cumSquare[i];
                            if (calc != expectedIndent) {
                                possible[r][c][s] = false;
                            }
                        }
                    }
                }
            }

            // Read second program
            Arrays.fill(roundOpen, 0);
            Arrays.fill(roundClose, 0);
            Arrays.fill(curlyOpen, 0);
            Arrays.fill(curlyClose, 0);
            Arrays.fill(squareOpen, 0);
            Arrays.fill(squareClose, 0);
            Arrays.fill(cumRound, 0);
            Arrays.fill(cumCurly, 0);
            Arrays.fill(cumSquare, 0);

            for (int i = 0; i < n2; i++) {
                String s = br.readLine();
                countSymbols(s, i);
            }

            // Compute cumulative for second program
            for (int i = 1; i < n2; i++) {
                cumRound[i] = cumRound[i-1] + roundOpen[i-1] - roundClose[i-1];
                cumCurly[i] = cumCurly[i-1] + curlyOpen[i-1] - curlyClose[i-1];
                cumSquare[i] = cumSquare[i-1] + squareOpen[i-1] - squareClose[i-1];
            }

            // For each line of second program, determine indentation
            for (int i = 0; i < n2; i++) {
                Set<Integer> possibleIndents = new HashSet<>();
                for (int r = 0; r <= 10; r++) {
                    for (int c = 0; c <= 10; c++) {
                        for (int s = 0; s <= 10; s++) {
                            if (possible[r][c][s]) {
                                int ind = r * cumRound[i] + c * cumCurly[i] + s * cumSquare[i];
                                // Also need to subtract closing symbols on this line (before content)
                                // Actually, the indentation is determined by cumulative BEFORE this line
                                // and then subtract closings on this line
                                ind -= r * roundClose[i] + c * curlyClose[i] + s * squareClose[i];
                                possibleIndents.add(ind);
                            }
                        }
                    }
                }
                if (possibleIndents.size() == 1) {
                    int ans = possibleIndents.iterator().next();
                    if (ans < 0) ans = 0; // indent can't be negative, but problem expects what formula gives
                    pw.print(ans);
                } else {
                    pw.print("-1");
                }
                if (i < n2 - 1) pw.print(" ");
            }
            pw.println();
        }
        pw.flush();
    }

    static void countSymbols(String s, int idx) {
        int rOpen = 0, rClose = 0, cOpen = 0, cClose = 0, sOpen = 0, sClose = 0;
        for (char ch : s.toCharArray()) {
            switch (ch) {
                case '(' : rOpen++; break;
                case ')' : rClose++; break;
                case '{' : cOpen++; break;
                case '}' : cClose++; break;
                case '[' : sOpen++; break;
                case ']' : sClose++; break;
            }
        }
        roundOpen[idx] = rOpen;
        roundClose[idx] = rClose;
        curlyOpen[idx] = cOpen;
        curlyClose[idx] = cClose;
        squareOpen[idx] = sOpen;
        squareClose[idx] = sClose;
    }
}

