    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int countLeadingDots(String s) {
        int i = 0;
        while (i < s.length() && s.charAt(i) == '.') i++;
        return i;
    }

    static int[] countBrackets(String s) {
        int[] c = new int[6];
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            switch (ch) {
                case '(': c[0]++; break;
                case ')': c[1]++; break;
                case '{': c[2]++; break;
                case '}': c[3]++; break;
                case '[': c[4]++; break;
                case ']': c[5]++; break;
            }
        }
        return c;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        String first = fs.next();
        if (first == null) return;
        int p = Integer.parseInt(first);
        int q = fs.nextInt();

        String[] master = new String[p];
        String[] target = new String[q];

        for (int i = 0; i < p; i++) master[i] = fs.next();
        for (int i = 0; i < q; i++) target[i] = fs.next();

        boolean[][][] possible = new boolean[21][21][21];

        int rOpen = 0, cOpen = 0, sOpen = 0;
        for (int i = 0; i < p; i++) {
            int dots = countLeadingDots(master[i]);

            if (i > 0) {
                for (int R = 1; R <= 20; R++) {
                    for (int C = 1; C <= 20; C++) {
                        for (int S = 1; S <= 20; S++) {
                            if (R * rOpen + C * cOpen + S * sOpen == dots) {
                                possible[R][C][S] = true;
                            }
                        }
                    }
                }
            }

            int[] cnt = countBrackets(master[i]);
            rOpen += cnt[0] - cnt[1];
            cOpen += cnt[2] - cnt[3];
            sOpen += cnt[4] - cnt[5];
        }

        int[] ans = new int[q];
        int tr = 0, tc = 0, ts = 0;

        for (int i = 0; i < q; i++) {
            if (i == 0) {
                ans[i] = 0;
            } else {
                int val = -2;
                boolean found = false;

                for (int R = 1; R <= 20; R++) {
                    for (int C = 1; C <= 20; C++) {
                        for (int S = 1; S <= 20; S++) {
                            if (!possible[R][C][S]) continue;
                            int cur = R * tr + C * tc + S * ts;
                            if (!found) {
                                val = cur;
                                found = true;
                            } else if (val != cur) {
                                val = -1;
                            }
                        }
                    }
                }

                if (!found) ans[i] = -1;
                else ans[i] = val;
            }

            int[] cnt = countBrackets(target[i]);
            tr += cnt[0] - cnt[1];
            tc += cnt[2] - cnt[3];
            ts += cnt[4] - cnt[5];
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            if (i > 0) sb.append(' ');
            sb.append(ans[i]);
        }
        System.out.println(sb);
    }
