import sys

def count_symbols(s):
    r = c = sqa = 0
    for ch in s:
        if ch == '(':
            r += 1
        elif ch == ')':
            r -= 1
        elif ch == '{':
            c += 1
        elif ch == '}':
            c -= 1
        elif ch == '[':
            sqa += 1
        elif ch == ']':
            sqa -= 1
    return r, c, sqa

def leading_dots(s):
    i = 0
    while i < len(s) and s[i] == '.':
        i += 1
    return i

def solve():
    input = sys.stdin.readline
    p, q = map(int, input().split())

    prog1 = [input().rstrip('\n') for _ in range(p)]
    prog2 = [input().rstrip('\n') for _ in range(q)]

    # Find all possible (R, C, S) in 1..20 that fit the first program
    possible = []

    # Prefix counts before each line in prog1
    pre1 = []
    r = c = s = 0
    for line in prog1:
        pre1.append((r, c, s))
        dr, dc, ds = count_symbols(line)
        r += dr
        c += dc
        s += ds

    for R in range(1, 21):
        for C in range(1, 21):
            for S in range(1, 21):
                ok = True
                for i in range(1, p):
                    dots = leading_dots(prog1[i])
                    pr, pc, ps = pre1[i]
                    if dots != R * pr + C * pc + S * ps:
                        ok = False
                        break
                if ok:
                    possible.append((R, C, S))

    # Apply to prog2
    pre2 = []
    r = c = s = 0
    for line in prog2:
        pre2.append((r, c, s))
        dr, dc, ds = count_symbols(line)
        r += dr
        c += dc
        s += ds

    ans = []
    for i in range(q):
        vals = set()
        pr, pc, ps = pre2[i]
        for R, C, S in possible:
            vals.add(R * pr + C * pc + S * ps)
        if len(vals) == 1:
            ans.append(str(vals.pop()))
        else:
            ans.append("-1")

    print(" ".join(ans))

if __name__ == "__main__":
    solve()

