map<int,int> learnIndent(vector<string>& prog) {
    map<int,int> result;
    int depth = 0;
    for (auto& line : prog) {
        // find first non-space
        int spaces = 0;
        while (spaces < (int)line.size() && line[spaces] == ' ') spaces++;
        // depth at start of line content
        // but we need to account for closers at start
        int d = depth;
        // update depth for this line
        for (char c : line) {
            if (c=='('||c=='['||c=='{') depth++;
            else if (c==')'||c==']'||c=='}') depth--;
        }
        result[d] = spaces; // might conflict
    }
    return result;
}

