#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int p, q;
    while (cin >> p >> q) {
        vector<string> P(p), Q(q);
        for (int i = 0; i < p; ++i) cin >> P[i];
        for (int i = 0; i < q; ++i) cin >> Q[i];

        vector<array<int, 3>> beforeP(p), beforeQ(q);

        // Counts before each line in P
        int r = 0, c = 0, s = 0;
        for (int i = 0; i < p; ++i) {
            beforeP[i] = {r, c, s};
            for (char ch : P[i]) {
                if (ch == '(') r++;
                else if (ch == ')') r--;
                else if (ch == '{') c++;
                else if (ch == '}') c--;
                else if (ch == '[') s++;
                else if (ch == ']') s--;
            }
        }

        // Try all possible coefficients 1..20
        vector<array<int, 3>> candidates;
        for (int R = 1; R <= 20; ++R) {
            for (int C = 1; C <= 20; ++C) {
                for (int S = 1; S <= 20; ++S) {
                    bool ok = true;
                    for (int i = 1; i < p; ++i) {
                        int dots = 0;
                        while (dots < (int)P[i].size() && P[i][dots] == '.') dots++;
                        int expected = R * beforeP[i][0] + C * beforeP[i][1] + S * beforeP[i][2];
                        if (dots != expected) {
                            ok = false;
                            break;
                        }
                    }
                    if (ok) candidates.push_back({R, C, S});
                }
            }
        }

        // Counts before each line in Q
        r = c = s = 0;
        for (int i = 0; i < q; ++i) {
            beforeQ[i] = {r, c, s};
            for (char ch : Q[i]) {
                if (ch == '(') r++;
                else if (ch == ')') r--;
                else if (ch == '{') c++;
                else if (ch == '}') c--;
                else if (ch == '[') s++;
                else if (ch == ']') s--;
            }
        }

        vector<int> ans(q, -1);
        ans[0] = 0; // first line always 0 indentation

        for (int i = 1; i < q; ++i) {
            int val = -1;
            bool same = true;
            for (auto &coef : candidates) {
                int cur = coef[0] * beforeQ[i][0] + coef[1] * beforeQ[i][1] + coef[2] * beforeQ[i][2];
                if (val == -1) val = cur;
                else if (val != cur) {
                    same = false;
                    break;
                }
            }
            if (same) ans[i] = val;
            else ans[i] = -1;
        }

        for (int i = 0; i < q; ++i) {
            if (i) cout << ' ';
            cout << ans[i];
        }
        cout << '\n';
    }

